mapper.select:
WITH RECURSIVE pool_tree AS ( SELECT id ,parent_id ,pool_name ,pool_type ,CAST(pool_name AS CHAR(2000)) AS pool_full_name ,CAST(LPAD(COALESCE(outer_sort, 0), 10, '0') AS CHAR(2000)) AS sort_path FROM ip_investment_pool WHERE is_deleted = 0 AND parent_id IS NULL
AND pool_type IN
#{poolType}
AND pool_type NOT IN
#{poolType}
UNION ALL SELECT child.id ,child.parent_id ,child.pool_name ,child.pool_type ,CONCAT(parent.pool_full_name, '/', child.pool_name) AS pool_full_name ,CONCAT(parent.sort_path, '/', LPAD(COALESCE(child.inner_sort, 0), 10, '0')) AS sort_path FROM ip_investment_pool child INNER JOIN pool_tree parent ON parent.id = child.parent_id WHERE child.is_deleted = 0
AND child.pool_type IN
#{poolType}
AND child.pool_type NOT IN
#{poolType}
) SELECT id ,parent_id ,pool_name ,pool_full_name ,pool_type FROM pool_tree ORDER BY sort_path ASC ,id ASC

WITH source_guarantor AS ( SELECT issuer.s_info_windcode AS security_code ,issuer.s_info_compcode AS windcode ,issuer.s_info_compname AS windname ,issuer.s_info_typecode AS guarantor_type_code ,CASE issuer.s_info_typecode WHEN 115004000 THEN 1 WHEN 115203000 THEN 2 WHEN 115202000 THEN 3 WHEN 115201000 THEN 4 END AS guarantor_sort_no ,ROW_NUMBER() OVER ( PARTITION BY issuer.s_info_windcode, issuer.s_info_compcode ORDER BY CASE issuer.s_info_typecode WHEN 115004000 THEN 1 WHEN 115203000 THEN 2 WHEN 115202000 THEN 3 WHEN 115201000 THEN 4 END ASC ) AS row_num FROM ais_inv_ods.wind_cbondissuer issuer WHERE issuer.s_info_typecode IN (115004000, 115203000, 115202000, 115201000) AND issuer.s_info_compcode IS NOT NULL AND issuer.s_info_compcode != '' AND issuer.s_info_windcode IN
#{securityCode}
)
,eligible_guarantor AS ( SELECT security_code ,windcode ,windname ,guarantor_type_code ,guarantor_sort_no FROM source_guarantor WHERE row_num = 1 )
,ranked_grade AS ( SELECT grade.windcode ,grade.windname ,grade.total_score ,grade.ts ,ROW_NUMBER() OVER ( PARTITION BY grade.windcode ORDER BY grade.ts DESC ) AS row_num FROM ais_inv_analysis.v_inv_grade_result grade WHERE EXISTS ( SELECT 1 FROM eligible_guarantor eligible WHERE eligible.windcode = grade.windcode ) )
SELECT eligible.security_code ,eligible.windcode ,COALESCE(grade.windname, eligible.windname) AS windname ,eligible.guarantor_type_code ,grade.total_score ,grade.ts FROM eligible_guarantor eligible INNER JOIN ranked_grade grade ON grade.windcode = eligible.windcode AND grade.row_num = 1 AND grade.total_score IS NOT NULL ORDER BY eligible.security_code ASC ,eligible.guarantor_sort_no ASC ,grade.ts DESC ,eligible.windcode ASC
